        private void ExportRacingReportHeader(ref ExcelWorksheet wsReport, int startCol, ref int currentRow,
                                             bool isDirect, bool isRacingBySport, bool isRacingDetail,
                                             string reportHeaderTitle)
        {
            //var typeTilte = isDirect ? "Sporttype" : (isRacingBySport ? "Bettype" : "Race");            
            var excelGemboxUtils = new ExcelGemboxUtils();
            var bgHeader = excelGemboxUtils.GetStyleTitle(Color.FromArgb(205, 222, 255));
            var commonStyle = excelGemboxUtils.GetStyleText(255, 255, 255);
            ExcelCell currentCell;
            CellRange currentCellRange;
            var currentCol = startCol;

            currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, startCol, currentRow, startCol + 6);
            currentCellRange.Merged = true;
            currentCellRange.Style = commonStyle;
            currentCellRange.Style.HorizontalAlignment = HorizontalAlignmentStyle.Center;
            currentCellRange.Value = reportHeaderTitle;
            currentCellRange.Style.Font.Weight = ExcelFont.BoldWeight;
            currentRow++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "Bettype";
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "WinLoss";
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "Position";
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "Comm";
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "Line Total";
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "Turnover";
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgHeader;
            currentCell.Value = "Margin";
            currentCol++;
            currentRow++;
        }

        private void ExportRacingReportBody(ref ExcelWorksheet wsReport, List<DailyWinLoss2hItem> reportData,
                                            int startCol, ref int currentRow)
        {
            var excelGemboxUtils = new ExcelGemboxUtils();
            var bgTitleForEachGroup = excelGemboxUtils.GetStyleTitle(Color.FromArgb(255, 255, 255));
            var numberDefaultFormat = GetStyleIntNumberLiveCasino(".00", Color.FromArgb(253, 252, 252), false, false);
            var bgLineTotalFormat = excelGemboxUtils.GetStyleIntNumber(".00", Color.FromArgb(130, 199, 255), true, true);

            var bgColor = Color.FromArgb(255, 255, 255);
            var commonStyle = excelGemboxUtils.GetStyleText(bgColor.R, bgColor.G, bgColor.B);
            var bgFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, false, true);
            var bgFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", bgColor, false, true);
            var bgTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, true, true);

            var evenRowColor = Color.FromArgb(205, 222, 243);
            var evenRowcommonStyle = excelGemboxUtils.GetStyleText(evenRowColor.R, evenRowColor.G, evenRowColor.B);
            var evenRowbgFormat = excelGemboxUtils.GetStyleIntNumber(".00", evenRowColor, false, true);
            var evenRowbgFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", evenRowColor, false, true);
            var evenRowbgTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", evenRowColor, true, true);
            ExcelCell currentCell;

            var isEvenRow = true;
            foreach (var dailyWLRow in reportData)
            {
                var currentCol = startCol;
                switch (dailyWLRow.RowTypeDWL2h.Id)
                {
                    case RowTypeConstants.Normal:
                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowcommonStyle : commonStyle);
                        currentCell.Value = dailyWLRow.Name;
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.WinLoss);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.Position);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.Commission);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.LineTotal);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.Turnover);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        if (CastAide.AsDouble(dailyWLRow.Turnover) != 0)
                        {
                            currentCell.Style = (isEvenRow ? evenRowbgFormatPercent : bgFormatPercent);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDouble(dailyWLRow.Margin) / 100;
                        }
                        else
                        {
                            currentCell.Style = (isEvenRow ? evenRowbgFormatPercent : bgFormatPercent);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = "N/A";
                        }
                        currentCol++;
                        currentRow++;
                        isEvenRow = !isEvenRow;
                        break;
                    case RowTypeConstants.EmptyRow:
                        this.ExportEmptyRow(ref wsReport, ref currentRow, startCol, startCol + 6);
                        isEvenRow = true;
                        break;
                }
            }
        }

        private void ExportRacingDetailReportBody(ref ExcelWorksheet wsReport, List<DailyWinLoss2hItem> reportData,
                                           int startCol, ref int currentRow, DailyWinLoss2hParam param)
        {
            var excelGemboxUtils = new ExcelGemboxUtils();
            var bgTitleForEachGroup = excelGemboxUtils.GetStyleTitle(Color.FromArgb(255, 255, 255));
            var numberDefaultFormat = GetStyleIntNumberLiveCasino(".00", Color.FromArgb(253, 252, 252), false, false);
            var bgLineTotalFormat = excelGemboxUtils.GetStyleIntNumber(".00", Color.FromArgb(130, 199, 255), true, true);

            var bgColor = Color.FromArgb(255, 255, 255);
            var commonStyle = excelGemboxUtils.GetStyleText(bgColor.R, bgColor.G, bgColor.B);
            var bgFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, false, true);
            var bgFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", bgColor, false, true);
            var bgTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, true, true);

            var evenRowColor = Color.FromArgb(205, 222, 243);
            var evenRowcommonStyle = excelGemboxUtils.GetStyleText(evenRowColor.R, evenRowColor.G, evenRowColor.B);
            var evenRowbgFormat = excelGemboxUtils.GetStyleIntNumber(".00", evenRowColor, false, true);
            var evenRowbgFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", evenRowColor, false, true);
            var evenRowbgTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", evenRowColor, true, true);

            ExcelCell currentCell;
            CellRange currentCellRange;
            var isEvenRow = true;

            foreach (var dailyWLRow in reportData)
            {
                var currentCol = startCol;
                switch (dailyWLRow.RowTypeDWL2h.Id)
                {
                    case RowTypeConstants.Normal:
                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowcommonStyle : commonStyle);
                        currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Center;
                        int raceNumber = 0;

                        if (param.SportType == 181)
                        {
                            currentCell.Value = String.Format("{0: HH:mm}", CastAide.AsDateTime(dailyWLRow.Name));
                        }
                        else
                        {
                            if (!Int32.TryParse(dailyWLRow.Name, out raceNumber))
                            {
                                currentCell.Value = dailyWLRow.Name;
                            }
                            else
                            {
                                currentCell.Value = raceNumber;
                            }
                        }

                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.WinLoss);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.Position);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.Commission);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.LineTotal);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        currentCell.Style = (isEvenRow ? evenRowbgFormat : bgFormat);
                        currentCell.Value = CastAide.AsDecimal(dailyWLRow.Turnover);
                        currentCol++;

                        currentCell = wsReport.Cells[currentRow, currentCol];
                        if (CastAide.AsDouble(dailyWLRow.Turnover) != 0)
                        {
                            currentCell.Style = (isEvenRow ? evenRowbgFormatPercent : bgFormatPercent);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = CastAide.AsDouble(dailyWLRow.Margin) / 100;
                        }
                        else
                        {
                            currentCell.Style = (isEvenRow ? evenRowbgFormatPercent : bgFormatPercent);
                            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                            currentCell.Value = "N/A";
                        }

                        currentCol++;
                        currentRow++;
                        isEvenRow = !isEvenRow;
                        break;
                    case RowTypeConstants.SportTotal:
                        ExportRacingReportTotal(ref wsReport, dailyWLRow, startCol, ref currentRow, false, true, false);
                        isEvenRow = true;
                        break;
                    case RowTypeConstants.EmptyRow:
                        this.ExportEmptyRow(ref wsReport, ref currentRow, startCol, startCol + 6);
                        isEvenRow = true;
                        break;
                    case RowTypeConstants.LeagueHeadLine:
                        currentCellRange = wsReport.Cells.GetSubrangeAbsolute(currentRow, startCol, currentRow, startCol + 6);
                        currentCellRange.Merged = true;
                        currentCellRange.Style = bgTitleForEachGroup;
                        currentCellRange.Style.HorizontalAlignment = HorizontalAlignmentStyle.Left;
                        currentCellRange.Value = dailyWLRow.Name;
                        currentRow++;
                        isEvenRow = true;
                        break;
                }
            }
        }

        private void ExportRacingReportTotal(ref ExcelWorksheet wsReport, DailyWinLoss2hItem totalData,
                                    int startCol, ref int currentRow,
                                    bool isFooter, bool isTotal, bool isDetail)
        {
            var bgColor = isFooter ? Color.FromArgb(205, 222, 255)
                           : isTotal ? Color.FromArgb(211, 225, 200) : Color.FromArgb(255, 255, 255);
            var excelGemboxUtils = new ExcelGemboxUtils();
            var commonStyle = excelGemboxUtils.GetStyleText(255, 255, 255);

            var bgFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, isDetail && isFooter ? true : false, true);
            var bgFormatPercent = excelGemboxUtils.GetStyleIntNumber(".00%", bgColor, isDetail && isFooter ? true : false, true);
            var bgLineTotalFormat = excelGemboxUtils.GetStyleIntNumber(".00", Color.FromArgb(130, 199, 255), true, true);
            var bgTurnoverFormat = excelGemboxUtils.GetStyleIntNumber(".00", bgColor, true, true);
            var numberDefaultFormat = GetStyleIntNumberLiveCasino(".00", bgColor, false, false);

            ExcelCell currentCell;
            var currentCol = startCol;
            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = numberDefaultFormat;
            currentCell.Style.Font.Weight = ExcelFont.BoldWeight;
            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
            currentCell.Value = totalData.Name;
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgFormat;
            currentCell.Value = CastAide.AsDecimal(totalData.WinLoss);
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgFormat;
            currentCell.Value = CastAide.AsDecimal(totalData.Position);
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgFormat;
            currentCell.Value = CastAide.AsDecimal(totalData.Commission);
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgLineTotalFormat;
            currentCell.Value = CastAide.AsDecimal(totalData.LineTotal);
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            currentCell.Style = bgTurnoverFormat;
            currentCell.Value = CastAide.AsDecimal(totalData.Turnover);
            currentCol++;

            currentCell = wsReport.Cells[currentRow, currentCol];
            if (CastAide.AsDouble(totalData.Turnover) != 0)
            {
                currentCell.Style = bgFormatPercent;
                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                currentCell.Value = CastAide.AsDouble(totalData.Margin) / 100;
            }
            else
            {
                currentCell.Style = bgFormatPercent;
                currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
                currentCell.Value = "N/A";
            }

            currentCol++;
            currentRow++;
        }

        #endregion HorseRacingReport
    }
}